class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        for j in range(1, n):
            dp[j] = max(dp[i] + (j - i) * nums[j] for i in range(j))
        return dp[-1]

