class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> dp(n, 0);
        for (int j = 1; j < n; j++)
            for (int i = 0; i < j; i++)
                dp[j] = max(dp[j], dp[i] + (long long)(j - i) * nums[j]);
        return dp[n - 1];
    }
};

