        st, dp = [], [0] * len(nums)
        for j, x in enumerate(nums):
            while st and nums[st[-1]] <= x: st.pop()
            p = st[-1] if st else 0
            dp[j] = (dp[p] if st else 0) + (j - p) * x
            st.append(j)
        return dp[-1]

