        vector<int> st;
        for (int j = 0; j < n; j++) {
            while (!st.empty() && nums[st.back()] <= nums[j]) st.pop_back();
            int p = st.empty() ? 0 : st.back();
            dp[j] = (st.empty() ? 0 : dp[p]) + (long long)(j - p) * nums[j];
            st.push_back(j);
        }
        return dp[n - 1];
