class Solution {
    public int maxScore(int[] nums) {
        int n = nums.length;
        long[] dp = new long[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int j = 0; j < n; j++) {
            while (!st.isEmpty() && nums[st.peek()] <= nums[j]) st.pop();
            boolean empty = st.isEmpty();
            int p = empty ? 0 : st.peek();
            dp[j] = (empty ? 0 : dp[p]) + (long)(j - p) * nums[j];
            st.push(j);
        }
        return (int) dp[n - 1];
    }
}

